import random, itertools, json
from typing import List, Dict, Any
from problems import NaeThreeSat, ThreeColoring
from reduce import reduce


def nae_bruteforce(instance: Dict[str, Any]) -> bool:
    NaeThreeSat.validate(instance)
    m = instance['num_vars']
    clauses = instance['clauses']
    if not clauses:
        return True
    for assign in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            vals = []
            for lit in clause:
                var = abs(lit) - 1
                val = assign[var]
                vals.append(val if lit > 0 else not val)
            if all(vals) or not any(vals):
                ok = False
                break
        if ok:
            return True
    return False


def threecolor_bruteforce(instance: Dict[str, Any]) -> bool:
    ThreeColoring.validate(instance)
    n = instance['n']
    edges = [(u, v) for u, v in instance['edges']]
    for colors in itertools.product(range(3), repeat=n):
        good = True
        for u, v in edges:
            if colors[u] == colors[v]:
                good = False
                break
        if good:
            return True
    return False


def random_instance():
    # random m up to 5
    m = random.randint(0, 5)
    # decide clause count, ensure if m<3 then 0 clauses
    max_clauses = 5
    if m < 3:
        clause_cnt = 0
    else:
        clause_cnt = random.randint(0, max_clauses)
    clauses = []
    vars_list = list(range(1, m+1))
    for _ in range(clause_cnt):
        chosen = random.sample(vars_list, 3)
        clause = []
        for v in chosen:
            lit = v if random.choice([True, False]) else -v
            clause.append(lit)
        clauses.append(clause)
    return {'num_vars': m, 'clauses': clauses}


def run_tests(trials=200):
    passed = 0
    for _ in range(trials):
        inst = random_instance()
        sat = nae_bruteforce(inst)
        red = reduce(inst)
        col = threecolor_bruteforce(red)
        if sat == col:
            passed += 1
        else:
            print('FAIL')
            print('inst', json.dumps(inst))
            print('red', json.dumps(red))
            print('sat', sat, 'col', col)
            break
    print(f'Passed {passed}/{trials}')
    verdict = {'verified': passed == trials, 'tests_run': trials, 'tests_passed': passed}
    with open('verdict.json', 'w') as f:
        json.dump(verdict, f)

if __name__ == '__main__':
    run_tests(200)
EOF"}

